const app = document.querySelector('#app');
const dialog = document.querySelector('#book-dialog');
const form = document.querySelector('#add-book-form');
const formError = document.querySelector('#form-error');
const toast = document.querySelector('#toast');

const palettes = ['sage', 'terracotta', 'blue', 'ochre', 'plum'];

function escapeHtml(value = '') {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function initials(title) {
  return title.trim().split(/\s+/).slice(0, 2).map((word) => word[0]).join('').toUpperCase() || 'B';
}

function paletteFor(book) {
  return palettes[[...book.id].reduce((sum, character) => sum + character.charCodeAt(0), 0) % palettes.length];
}

function cover(book, size = '') {
  return `<span class="book-cover ${paletteFor(book)} ${size}" aria-hidden="true">
    <span class="cover-mark">${escapeHtml(initials(book.title))}</span>
    <span class="cover-rule"></span>
    <span class="cover-title">${escapeHtml(book.title)}</span>
    <span class="cover-author">${escapeHtml(book.author)}</span>
  </span>`;
}

function formatDate(value) {
  if (!value) return '';
  return new Intl.DateTimeFormat(undefined, { month: 'short', year: 'numeric' }).format(new Date(value));
}

